mapper.select:
SELECT page.* FROM ( SELECT f.id, f.uid, f.friend_uid, f.nickname, u.id AS profile_uid, u.name, COALESCE(f.nickname_sort_key, u.name_sort_key, _utf8mb4'1:') COLLATE utf8mb4_bin AS sort_key FROM user_friend f LEFT JOIN `user` u ON u.id = f.friend_uid WHERE f.uid = #{uid} AND f.delete_status = 0 AND f.black_status = 0 ) page
WHERE page.sort_key > CONVERT(#{sortKey} USING utf8mb4) COLLATE utf8mb4_bin OR (page.sort_key = CONVERT(#{sortKey} USING utf8mb4) COLLATE utf8mb4_bin AND page.id > #{relationId})
ORDER BY page.sort_key COLLATE utf8mb4_bin , page.id LIMIT #{limit}
